 app.querySelectorAll('[data-memory-trade-answer]').forEach(b=>b.onclick=()=>{s.answer=b.dataset.memoryTradeAnswer;s.checked=false;writeDraft(active.id,s);renderMemoryTrade();app.querySelector(`[data-memory-trade-answer="${s.answer}"]`).focus();});
