 app.querySelectorAll('[data-credit-answer]').forEach(b=>b.onclick=()=>{s.answer=b.dataset.creditAnswer;s.checked=false;writeDraft(active.id,s);renderAmortCredit();app.querySelector(`[data-credit-answer="${s.answer}"]`).focus();});
 app.querySelector('#credit-check').onclick=()=>{s.checked=true;writeDraft(active.id,s);if(amortCreditComplete(s)){if(!completed.includes(active.id))completed.push(active.id);save();if(storageAvailable)clearDraft(active.id);}renderAmortCredit();app.querySelector('#credit-check').focus();};
